package org.example.maniacrevolution.character.survivor;

import org.example.maniacrevolution.character.*;
import org.example.maniacrevolution.engineer.EngineerRules;

public final class EngineerClass extends CharacterClass {
    public EngineerClass() {
        super("engineer", "Инженер", CharacterType.SURVIVOR, "Этот проход пока закрыт. А шум — вообще не отсюда.", EngineerRules.CLASS_ID, 4);
        addTag("Поддержка"); addTag("Контроль"); addTag("Отвлечение");
        addFeature("Утилизация", "Старт: 40 скрапа, запас до 60. Личный новый прогресс компьютеров, включая QTE, даёт металл: 10 за 10% компьютера. До 120 за матч; повторная зарядка отката не оплачивается.");
        addFeature("Баррикады", "20 скрапа. До пяти, живут 120 с. Установка 2,5 с; небольшой сдвиг и поворот допустимы. Маньяк удерживает ЛКМ 2 с для разрушения, в том числе в приключении.");
        addFeature("Акустические панели", "25 скрапа. До восьми панелей, по три запуска. Пульт воспроизводит бег или работу у компьютера в течение 10 с. Перезарядка 15 с; после третьего воспроизведения панель хлопает и исчезает.");
        addFeature("Гайки на завтрак", "25 скрапа, подготовка 2 с. Каждая порция добавляет 3 защиты, до 20. Защита поглощает урон перед HP и расходуется только на поглощённое количество. Повторное поедание без КД.");
        addItem("Планшет инженера", "ПКМ или V: мастерская. Выберите постройку, наведите проекцию на пол и нажмите ЛКМ. ПКМ или Esc — отмена. Металл списывается только после успешной установки.");
        addItem("Пульт панелей", "ПКМ: список собственных панелей, координат, зарядов и перезарядки. Выберите звуковой сценарий и запустите панель.");
        addItem("Складная баррикада", "ПКМ предметом по полу: сборка за 2,5 с с расходом предмета. Задерживает всех игроков. Shift + ПКМ 1 с — разбор без возврата скрапа.");
        addItem("Звуковая панель", "ПКМ предметом по полу: сборка за 2,5 с. Стационарная приманка с тремя запусками с пульта. Удержание ЛКМ маньяком 2 с — разрушение.");
    }
}
